/* @lc app=leetcode id=923 lang=kotlin */ class Solution { fun threeSumMulti(arr: IntArray, target: Int): Int = LongArray(101).also { c -> arr.forEach { c[it]++ } }.let { c -> (0..100).sumOf { i -> (i..100).sumOf { j -> (target - i - j).let { k -> if (k < j || k > 100) 0L else (if (i == j && j == k) c[i] * (c[i] - 1) * (c[i] - 2) / 6 else if (i == j) c[i] * (c[i] - 1) / 2 * c[k] else if (j == k) c[i] * (c[j] * (c[j] - 1) / 2) else c[i] * c[j] * c[k]) % 1_000_000_007 } } % 1_000_000_007 } % 1_000_000_007 }.toInt() }